<!doctype html>
<html>
<head>
<meta charset="utf-8">

<style>
    @import url('http://fonts.googleapis.com/css2?family=Roboto:wght@100;300;400;500;700;900&display=swap');
    
    body{
     font-family: 'Roboto', sans-serif;
    }
    .f-left{
      float: left;
    }
    .f-right{
      float: right;
    }
    .t-right{
        text-align: right;
    }
    .t-center{
        text-align: center;
    }
    .t-left{
        text-align: left;
    }
	.logo-h{
max-width: 71px;
margin: auto;
width: 100%;
}
    .border{
      border:1px solid #000;
      border-radius: 10px;
    }
    .full-width{
        padding: 15px;
        overflow: hidden;
    }
    .report p strong{
        font-size: 22px;
    }
    .report p{
        color: #000;
        margin:0px;
        padding-top: 8px;
        font-size: 13px;
    }
    .report p a{
        color: #000;
    }
    .head-block {
    overflow: hidden;
    margin-bottom: 15px;
    }
    .full-width h4 {
        margin: 0px;
        color: #000;
        font-size: 60px;
    }
    .border-bottom{
        border-bottom: 1px solid  #0000006e;
        overflow: hidden;
        padding-top: 15px;
        margin-bottom: 15px;
    }
    .vehicle-information .information-d{
        padding-top: 5px;
    }
    .vehicle-information ul{
        margin-top: 0px;
        padding-left: 15px;
    }
    .vehicle-information ul li {
        width: 45%;
        float: left;
        color: #000;
        font-size: 18px;
        display: block;
        padding: 12px 0px 0px;
        position: relative;
        padding-left: 25px;
    }
	.vehicle-information ul li strong {font-size: 22px;}
	
    img.icon-logo {
        width: 27px;
        position: absolute;
        left: -6px;
        top: 14px;
    }
    .information-detail h3{
        margin: 0px;
        color: #000;
        font-weight: 300;
        font-size: 32px;
    }
    .information-detail h5{
        margin: 0px;
        color: #000;
        font-weight: 300;
        font-size:25px;
    }
    .information-detail h1{
        font-size: 30px;
        font-weight: bold;
        color: #000;
        margin: 0px;
    }
    .information-detail h1 sub{
        font-size: 20px;
        font-weight: 300;
    }
    .w-full{
        width: 100%;
    }
    .bottom-text{
        width: 100%;
        overflow: hidden;
        line-height: 15px;
    }
    .vehicle-information {
    overflow: hidden;
}
.logo-m{max-width:350px; width:100%;}
.report-header-right.f-right.t-right h2 {font-family: 'Russo One', sans-serif;}
</style>
</head>
<body style="width:900px;margin:100px auto;">
    <div class="report" style="border: 1px solid #000; padding: 10px;"> 
        <div class="head-block">
            <div class="report-header-left f-left" style="width:50%;">
                <img src="{{LOGO}}" class="logo-m"/>
				<!--<img src=" data:image/jpeg;base64,
" class="logo-h"/>-->
            </div>
            <div class="report-header-right f-right t-right" style="width:50%;">
                <h2> Financing & Extended<br/> Warranty available </h2>
            </div>
        </div>
        <div class="border full-width">
            <div class="report-header-left t-center">
                <h4> {{YEAR}} {{MAKE}} {{MODEL}}</h4>
                <p><span class="vin" style="font-size: 20px;"> <strong style="font-size: 20px;"> VIN: </strong> {{VIN}}</span> 
				<strong style="font-size: 25px;display:block;"> Stock #:   {{STOCK}} </strong></p>
                <p style="font-size: 60px;font-weight:700;">{{ODOMETER}} {{KM_MILES}}</p>
            </div>
           <div class="border-bottom" style="width:100%;"></div>
            <div class="vehicle-information">
                <p class="t-center"><strong>Vehicle Information</strong></p>
                <ul>
                    <li><img src="data:image/png;base64," class="icon-logo" /> Body Type: <strong>{{BODY}}</strong></li>
                    <li><img src="data:image/png;base64," class="icon-logo" />Doors: <strong>{{DOOR}}</strong></li>
                    <li><img src="data:image/png;base64," class="icon-logo" />Engine: <strong>{{ENGINE}}</strong></li>
                    <li><img src="data:image/png;base64," class="icon-logo" />Cylinder: <strong>{{CYLINDER}}</strong></li>
                    <li><img src="data:image/png;base64," class="icon-logo" />Transmission: <strong>{{TRANSMISSION}}</strong></li>
                    <li><img src="data:image/png;base64," class="icon-logo" />Drivetrain: <strong>{{DRIVETRAIN}}</strong></li>
                    <li><img src="data:image/png;base64," class="icon-logo" />Passengers: <strong>{{PASSENGERS}}</strong></li>
                    <li><img src="data:image/png;base64," class="icon-logo" />Exterior Colour: <strong>{{EXTERIOR_COLOR}}</strong></li>
                    <li><img src="data:image/png;base64," class="icon-logo" />Interior Colour: <strong>{{INTERIOR_COLOR}}</strong></li>
                </ul>
            </div> 
           
		   <div class="report-header-right t-center information-detail" style="margin-top: 20px;">
                
                <p><strong style="font-size:100px;padding-right: 15px; letter-spacing:2px;">${{PRICE}}</strong>  <span style="font-size: 18px;display: block;text-align: right;">+ Taxes and Licensing</span> <!-- <strong style="font-size:30px; color: red;">$42,750</strong>--></p>
               
            </div>
			
            <div class="border-bottom" style="width:100%;"></div>
           <div class="border-bottom" style="width:100%;"></div> 
            <div class="information-detail">
                <div class="report-header-left f-left t-center" style="width:20%;padding: 25px 10px;">
                    <p style="padding-top: 0px;font-size: 18px;padding-bottom:8px;"> SCAN ME!</p>                    
                    {{QR}}
					<img src="data:image/png;base64,
" style="max-width:80px;width:100%;"/>
                </div>
                <div class="report-header-left f-left t-center" style="width:73%;padding: 75px 10px 25px 10px;">
                <img src="data:image/jpeg;base64,
" style="max-width:90%;width:100%;"/>

<div class="information-detail" style="width: 68%;float: right;margin-top: -100px;position: relative;z-index: 99999;">
               <p style="padding-top: 0px;font-size: 18px;padding-bottom:8px;"><strong>Fuel Economy</strong></p>
                <div class="report-header-left f-left t-center" style="width:30%;padding: 10px 10px;">
                    <h5>CITY</h5>
                    <h1>{{FUEL_CITY}}</h1>
                    <p><strong>L/100 {{KM_MILES}} </strong></p>
                </div>
                
                <div class="report-header-left f-left t-center" style="width:25%;padding: 10px 10px;">
                   <img src="data:image/png;base64," class="logo-h"/>
                </div>
				<div class="report-header-left f-left t-center" style="width:30%;padding: 10px 10px;">
                    <h5>HIGHWAY</h5>
                    <h1>{{FUEL_HWY}}</h1>
                    <p><strong>L/100 {{KM_MILES}}</strong></p>
                </div>
            </div> 
			
</div>
<div class="bottom-text t-center">
                 <p style="font-size:9px;">*Prices fo this vehicle may not include charges such as License; Registration Fees; Local Taxes; Finance Charges; or Delivery Fees. Every reasonable effort is made to ensure the accuracy of the information listed above. Vehicle pricing, incentives, options (including standard equipment), and technical specifications listed may not match the exact vehicle displayed. Please confirm with a sales representative the accuracy of this information.</p>
                </div>
            </div>
        </div>
    </div>
</body>
</html>